// spec: .qa/e2e/specs/tehilim.md
// seed: tests/seed.user1.spec.ts
import { test, expect } from '@playwright/test';
import * as path from 'path';
import { suppressMilestoneWindow } from '../_helpers/milestone';

test.use({ storageState: path.resolve(__dirname, '../../../auth/user1.json') });

test.describe('Чтение תהילים', () => {
  test('TH-01 Экран פרק תהילים — без полосы перехода; «סיים קריאה», «האזן להקראה», ⓘ, «חזק את חברך», нижняя навигация #6a86f7da @prod-safe', async ({ page }) => {
    await suppressMilestoneWindow(page); // окно уровня «עלית דרגה» не должно перекрывать экран
    // 1. До перехода: подмена `navigator.share` (сохраняет текст в `window.__shared`).
    await page.addInitScript(() => {
      Object.defineProperty(navigator, 'share', {
        configurable: true,
        value: (data: { text?: string; message?: string; url?: string }) => {
          (window as any).__shared = data.text ?? [data.message, data.url].filter(Boolean).join('\n');
          return Promise.resolve();
        },
      });
    });

    // 2. Открыть `/tehilim/72`.
    await page.goto('/tehilim/72');
    await expect(page.getByRole('heading', { level: 1, name: 'תהילים ע״ב' })).toBeVisible({ timeout: 20_000 });
    await expect(page.getByText('לשלמה אלהים משפטיך', { exact: true })).toBeVisible();
    // Порядок огласовок на странице может отличаться от литерала — сравниваем после normalize('NFC') обеих сторон.
    await expect
      .poll(async () => (await page.locator('body').innerText()).normalize('NFC').includes('א לִשְׁלֹמֹה'.normalize('NFC')))
      .toBe(true);
    await expect(page.getByText(/מקור: Sefaria\.org/)).toBeVisible();
    // Нет полосы перехода между главами.
    await expect(page.getByText('פרק ע״א')).toHaveCount(0);
    await expect(page.getByText('פרק ע״ג')).toHaveCount(0);
    // Под текстом: «סיים קריאה» (НЕ нажимать), «האזן להקראה», «חזק את חברך».
    await expect(page.getByRole('button', { name: 'סיים קריאה' })).toBeVisible();
    await expect(page.getByText('האזן להקראה', { exact: true })).toBeVisible();
    await expect(page.getByRole('button', { name: 'השמע' })).toBeDisabled();
    await expect(page.getByText('אין הקראה לפרק הזה')).toBeVisible();
    await expect(page.getByRole('button', { name: 'חזק את חברך' })).toBeVisible();

    // 3. Нажать ⓘ «הסבר על הפרק», прочитать окно, нажать «סגירה והמשך בקריאה».
    await page.getByRole('button', { name: 'הסבר על הפרק' }).click();
    const info = page.getByRole('dialog');
    await expect(info.getByRole('heading', { name: 'על תהילים ע״ב' })).toBeVisible();
    await expect(info.getByText(/עדיין אין הסבר מאושר/)).toBeVisible();
    await info.getByRole('button', { name: 'סגירה והמשך בקריאה' }).click();
    await expect(page.getByRole('dialog')).toHaveCount(0);

    // 4. Нажать «חזק את חברך» → прочитать окно → «המשך לשיתוף»; прочитать `window.__shared`.
    await page.getByRole('button', { name: 'חזק את חברך' }).click();
    const share = page.getByRole('alert');
    await expect(share.getByText('קראתי עכשיו תהילים ע״ב (לשלמה אלהים משפטיך). מצטרפים לקרוא גם?')).toBeVisible();
    await expect(share.getByText(/https:\/\/zichui-harabim\.expo\.app\/tehilim\/72/)).toBeVisible();
    await expect(share.getByRole('button', { name: 'ביטול' })).toBeVisible();
    await share.getByRole('button', { name: 'המשך לשיתוף' }).click();
    await expect
      .poll(() => page.evaluate(() => (window as any).__shared))
      .toBe('קראתי עכשיו תהילים ע״ב (לשלמה אלהים משפטיך). מצטרפים לקרוא גם?\nhttps://zichui-harabim.expo.app/tehilim/72');

    // 5. «סיים קריאה» НЕ нажимать. Нижняя навигация; нет горизонтальной прокрутки.
    await expect(page.getByRole('tab')).toHaveText(['תהילים', 'תפילות', 'בית', 'המסע שלי', 'ברכות']);
    const noHScroll = await page.evaluate(() => document.documentElement.scrollWidth <= window.innerWidth);
    expect(noHScroll).toBe(true);
  });
});
